/**
 * Authoring-path validation for plan/apply.
 *
 * Workspace root = nearest ancestor directory that contains `tsconfig.json`
 * (the org root written by `elementum import org`).
 *
 * From that root, the relative path must be fully valid for the authenticated
 * tenant:
 *
 *   elements/<ref>/<ref>.ts
 *   apps/<ref>/<ref>.ts
 *   tables/<ref>/<ref>.ts
 *   {apps|elements}/<ref>/{automations,agents,…}/<name>.ts
 *
 * The org root itself must match auth:
 *   <org>/                 or
 *   <instance>/<org>/      (e.g. eu/sanofi)
 */
import { existsSync } from "node:fs";
import { basename, dirname, isAbsolute, join, relative, resolve, sep } from "node:path";
import { ENTITY_KIND_MODULES, ownFileBagsUnder } from "../../graph/index.js";
/** Org-root aspect bags from graph nodes parented by org with streamRoot + ownFile. */
const ASPECT_ROOTS = new Set(ENTITY_KIND_MODULES.flatMap((m) => {
    if (m.stream.role !== "streamRoot" || m.authoring.unit !== "ownFile")
        return [];
    if (!m.parents.some((e) => e.parent === "org"))
        return [];
    return [m.authoring.bag];
}));
/**
 * Child bags under apps|elements: union of own-file bags under app/element,
 * plus legacy authoring dirs not yet registered as graph kinds.
 */
const LEGACY_CHILD_BAGS = ["approval-chains", "tables", "fileReaders"];
const CHILD_BAGS = new Set([
    ...ownFileBagsUnder("app"),
    ...ownFileBagsUnder("element"),
    ...LEGACY_CHILD_BAGS,
]);
/** Instance folder names used in multi-instance parent workspaces. */
const INSTANCE_FOLDER_NAMES = new Set(["us", "eu", "stage", "dev", "local"]);
/**
 * Driver/helper convention: underscore-prefixed source files are helpers, except
 * digit-leading entity refs where ei's SanitizeName leading `_` survives into the
 * tsLabel (`_1GenerateJson` from `1. Generate JSON`). Those remain discoverable
 * own-file children — see issue #751.
 */
export function isAuthoringHelperFile(fileName) {
    const base = basename(fileName);
    if (!base.startsWith("_"))
        return false;
    const stem = base.replace(/\.(ts|js|mjs)$/, "");
    // `_1Foo`, `_3_1Bar` — managed entity refs, not helpers.
    return !/^\d/.test(stem.slice(1));
}
/** Walk up from `startDir` to the nearest directory that contains `tsconfig.json`. */
export function findOrgWorkspaceByTsconfig(startDir) {
    let cur = resolve(startDir);
    while (true) {
        if (existsSync(join(cur, "tsconfig.json")))
            return cur;
        const parent = dirname(cur);
        if (parent === cur)
            return undefined;
        cur = parent;
    }
}
/**
 * Validate a path relative to the org workspace root (posix-style segments).
 * Example: `elements/tag/tag.ts`, `apps/incident/automations/triage.ts`.
 */
export function assertRelativeAuthoringPath(relPath) {
    const rel = relPath.split(/[/\\]/).filter((p) => p && p !== ".").join("/");
    if (rel === "" || rel.includes("..")) {
        throw new Error(`Authoring path must be inside the org workspace: ${relPath}`);
    }
    const parts = rel.split("/");
    const file = parts[parts.length - 1];
    if (!/\.(ts|js|mjs)$/.test(file) || file.endsWith(".d.ts") || file.endsWith(".test.ts")) {
        throw new Error(`Not an entity source file: ${relPath}`);
    }
    if (isAuthoringHelperFile(file)) {
        throw new Error(`Not an entity source file: ${relPath}`);
    }
    const stem = file.replace(/\.(ts|js|mjs)$/, "");
    const bag = parts[0];
    // Org-owned table root (graph: table.authoring.bag) — special-cased path shape.
    if (bag === "tables") {
        if (parts.length === 3) {
            const refFolder = parts[1];
            if (refFolder !== stem) {
                throw new Error(`Table file must be tables/${refFolder}/${refFolder}.ts, got ${rel}`);
            }
            return;
        }
        if (parts.length === 2) {
            throw new Error(`Flat authoring path is not allowed (${bag}/${stem}.ts). ` +
                `Use ${bag}/${stem}/${stem}.ts instead.`);
        }
        if (parts.length === 4 && parts[2] === "search-tables")
            return;
        throw new Error(`Org-owned table authoring path must be tables/<ref>/<ref>.ts, got: ${rel}`);
    }
    if (!bag || !ASPECT_ROOTS.has(bag)) {
        throw new Error(`Authoring file must live under apps/<ref>/, elements/<ref>/, or tables/<ref>/ (from org workspace root), got: ${rel}`);
    }
    // apps|elements / <ref> / <ref>.ts
    if (parts.length === 3) {
        const refFolder = parts[1];
        if (refFolder !== stem) {
            throw new Error(`Aspect file must be ${bag}/${refFolder}/${refFolder}.ts, got ${rel}`);
        }
        return;
    }
    // apps|elements / <ref> / <bag> / <name>.ts
    if (parts.length === 4) {
        const childBag = parts[2];
        if (!CHILD_BAGS.has(childBag)) {
            throw new Error(`Unknown bag "${childBag}" under ${bag}/${parts[1]}/ — expected one of ${[...CHILD_BAGS].join(", ")}`);
        }
        return;
    }
    if (parts.length === 2) {
        throw new Error(`Flat authoring path is not allowed (${bag}/${stem}.ts). ` +
            `Use ${bag}/${stem}/${stem}.ts instead.`);
    }
    throw new Error(`Authoring path is too deep or malformed: ${rel}`);
}
/**
 * True for stream-root authoring files only — `apps/<ref>/<ref>.ts`,
 * `elements/<ref>/<ref>.ts`, or `tables/<ref>/<ref>.ts`. Own-file children
 * under a bag (`automations/`, `agents/`, …) are excluded so catalog
 * regeneration does not treat them as stream roots when passed an app/element
 * directory (issue #751).
 */
export function isStreamRootAuthoringFile(file) {
    const normalized = resolve(file).replace(/\.(ts|js|mjs)$/, "");
    const parts = normalized.split(sep);
    const rootIdx = Math.max(parts.lastIndexOf("apps"), parts.lastIndexOf("elements"), parts.lastIndexOf("tables"));
    if (rootIdx === -1)
        return false;
    const after = parts.slice(rootIdx);
    if (after.length !== 3)
        return false;
    return after[1] === after[2];
}
/**
 * Org root directory must be `<org>` or `<instance>/<org>` for this tenant.
 */
export function assertOrgRootMatchesTenant(orgRoot, tenant) {
    const orgSlug = tenant.organization.trim().toLowerCase();
    const instanceSlug = tenant.instance.trim().toLowerCase();
    if (orgSlug === "" || instanceSlug === "") {
        throw new Error("ei auth instance and organization are required to validate authoring paths.");
    }
    const root = resolve(orgRoot);
    const base = basename(root).toLowerCase();
    const parent = basename(dirname(root)).toLowerCase();
    if (base !== orgSlug) {
        throw new Error(`Org workspace folder must be "${orgSlug}" (ei auth organization), got "${base}" (${root})`);
    }
    if (INSTANCE_FOLDER_NAMES.has(parent) && parent !== instanceSlug) {
        throw new Error(`Org workspace is under instance folder "${parent}" but ei auth instance is "${instanceSlug}" (${root})`);
    }
}
/**
 * Absolute paths of org workspaces allowed for this auth tenant under `cwd`:
 * `<org>` and `<instance>/<org>`.
 */
export function approvedOrgWorkspaceRoots(tenant, cwd = process.cwd()) {
    const org = tenant.organization.trim();
    const instance = tenant.instance.trim();
    if (org === "" || instance === "")
        return [];
    return [resolve(cwd, instance, org)];
}
/**
 * Full plan/apply path gate.
 *
 * 1. Resolve org workspace via nearest `tsconfig.json`
 * 2. Relative path from that root must be a complete valid authoring path
 * 3. Org workspace folder must match authenticated org/instance
 */
export function assertAuthoringPathForTenant(file, tenant) {
    const abs = resolve(file);
    const orgRoot = findOrgWorkspaceByTsconfig(dirname(abs));
    if (orgRoot === undefined) {
        throw new Error(`No org workspace (tsconfig.json) found above ${abs}`);
    }
    const rel = relative(orgRoot, abs);
    if (rel.startsWith("..") || isAbsolute(rel)) {
        throw new Error(`Authoring file is outside org workspace ${orgRoot}: ${abs}`);
    }
    assertRelativeAuthoringPath(rel);
    assertOrgRootMatchesTenant(orgRoot, tenant);
}
/**
 * Layout-only check for discovery without a tenant context (tests).
 * Prefers validating relative to the nearest `tsconfig.json` org root; falls
 * back to requiring a valid `apps|elements/…` suffix in the absolute path.
 */
export function assertValidAuthoringLayout(file) {
    const abs = resolve(file);
    const orgRoot = findOrgWorkspaceByTsconfig(dirname(abs));
    if (orgRoot !== undefined) {
        const rel = relative(orgRoot, abs);
        if (!rel.startsWith("..") && !isAbsolute(rel)) {
            assertRelativeAuthoringPath(rel);
            return;
        }
    }
    // No tsconfig above the file — still reject obviously flat/misplaced paths
    // by inspecting the absolute path's apps|elements|tables suffix.
    const parts = abs.replace(/\.(ts|js|mjs)$/, "").split(sep);
    const idx = Math.max(parts.lastIndexOf("apps"), parts.lastIndexOf("elements"), parts.lastIndexOf("tables"));
    if (idx === -1) {
        throw new Error(`Authoring file must live under an org workspace with tsconfig.json ` +
            `(apps/<ref>/, elements/<ref>/, or tables/<ref>/): ${abs}`);
    }
    const suffix = parts.slice(idx).join("/");
    assertRelativeAuthoringPath(`${suffix}.ts`);
}
/** @deprecated Use {@link assertAuthoringPathForTenant}. */
export function assertUnderAuthenticatedOrgWorkspace(file, tenant) {
    assertAuthoringPathForTenant(file, tenant);
}
/** Build tenant path context from active `ei auth`. */
export function authoringTenantFromEiAuth(auth) {
    const organization = auth.organization.trim();
    const instance = auth.instance.trim();
    if (organization === "" || instance === "") {
        throw new Error("ei auth instance and organization are required.");
    }
    return { organization, instance };
}
